static_assert(__builtin_offsetof(SWindow, saved_viewport_height) == 52,
              "offsetof(SWindow, saved_viewport_height) != 52");
static_assert(__builtin_offsetof(SWindow, text_buffer) == 56,
              "offsetof(SWindow, text_buffer) != 56");
static_assert(__builtin_offsetof(SWindow, screen_backup_buffer) == 456,
              "offsetof(SWindow, screen_backup_buffer) != 456");
static_assert(__builtin_offsetof(SWindow, backup_x_offset) == 460,
              "offsetof(SWindow, backup_x_offset) != 460");
static_assert(__builtin_offsetof(SWindow, backup_y_offset) == 464,
              "offsetof(SWindow, backup_y_offset) != 464");
static_assert(__builtin_offsetof(SWindow, backup_width) == 468,
              "offsetof(SWindow, backup_width) != 468");
static_assert(__builtin_offsetof(SWindow, backup_height) == 472,
              "offsetof(SWindow, backup_height) != 472");
static_assert(__builtin_offsetof(SWindow, progress_start_time) == 476,
              "offsetof(SWindow, progress_start_time) != 476");
static_assert(__builtin_offsetof(SWindow, progress_percentage) == 480,
              "offsetof(SWindow, progress_percentage) != 480");
static_assert(__builtin_offsetof(SWindow, progress_timestamp) == 484,
              "offsetof(SWindow, progress_timestamp) != 484");

// ---- SWindowRect (16 bytes) ----
static_assert(sizeof(SWindowRect) == 16,
              "sizeof(SWindowRect) != 16");
static_assert(__builtin_offsetof(SWindowRect, left) == 0,
              "offsetof(SWindowRect, left) != 0");
static_assert(__builtin_offsetof(SWindowRect, top) == 4,
              "offsetof(SWindowRect, top) != 4");
static_assert(__builtin_offsetof(SWindowRect, right) == 8,
              "offsetof(SWindowRect, right) != 8");
static_assert(__builtin_offsetof(SWindowRect, bottom) == 12,
              "offsetof(SWindowRect, bottom) != 12");

